FUNCTION ROL_ARREAL
VAR_INPUT
    N : DINT;
END_VAR
VAR_IN_OUT
    INOUT : ARRAY[0..99] OF REAL;
END_VAR
VAR
    tmp : ARRAY[0..99] OF REAL;
    i : DINT;
    s : DINT;
END_VAR
s := N MOD 100;
IF s < 0 THEN
    s := s + 100;
END_IF;
FOR i := 0 TO 99 DO
    tmp[i] := INOUT[(i + s) MOD 100];
END_FOR
FOR i := 0 TO 99 DO
    INOUT[i] := tmp[i];
END_FOR
END_FUNCTION
